'use client';

import React from 'react';
import Link from 'next/link';
import { useSites } from '@/hooks/useSites';
import { SiteCard } from '@/components/SiteCard';
import { IncidentBanner } from '@/components/IncidentBanner';
import { Button } from '@/components/ui/Button';
import { PlusCircle, Activity, RefreshCw } from 'lucide-react';

export default function DashboardPage() {
  const { sites, isLoading, isError, refetch, isFetching, deleteSite, isDeleting } = useSites();

  // Find sites that are currently down
  const downSites = sites.filter((site) => site.last_status === 'down');
  const upSites = sites.filter((site) => site.last_status === 'up');

  return (
    <div className="space-y-6 animate-in fade-in duration-300">
      {/* Active Incident Warning Banner if any sites are down */}
      <IncidentBanner downSites={downSites} />

      {/* Page Title & Stats Overview */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-white flex items-center gap-2.5">
            Monitored Services
            <button
              onClick={() => refetch()}
              disabled={isFetching}
              className="text-[#8B949E] hover:text-white p-1 rounded transition-colors"
              title="Refresh status"
            >
              <RefreshCw className={`h-4 w-4 ${isFetching ? 'animate-spin' : ''}`} />
            </button>
          </h1>
          <p className="text-xs text-[#8B949E] mt-1">
            Realtime operational telemetry across all configured SaaS endpoints.
          </p>
        </div>

        {sites.length > 0 && (
          <div className="flex items-center gap-3 font-mono text-xs">
            <div className="px-3 py-1.5 rounded-[6px] bg-[#161B22] border border-[#30363D] flex items-center gap-2">
              <span className="w-2 h-2 rounded-full bg-[#00FF87]" />
              <span className="text-[#8B949E]">Operational:</span>
              <span className="text-white font-semibold">{upSites.length}</span>
            </div>
            <div className="px-3 py-1.5 rounded-[6px] bg-[#161B22] border border-[#30363D] flex items-center gap-2">
              <span className="w-2 h-2 rounded-full bg-[#FF4D4F]" />
              <span className="text-[#8B949E]">Downtime:</span>
              <span className="text-white font-semibold">{downSites.length}</span>
            </div>
          </div>
        )}
      </div>

      {/* Loading State */}
      {isLoading && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 py-12">
          {[1, 2, 3].map((i) => (
            <div
              key={i}
              className="h-48 rounded-lg bg-[#161B22] border border-[#30363D] animate-pulse"
            />
          ))}
        </div>
      )}

      {/* Error State */}
      {isError && (
        <div className="p-6 rounded-lg bg-[#FF4D4F]/10 border border-[#FF4D4F]/30 text-center">
          <p className="text-sm text-[#FF4D4F] font-semibold">Failed to load monitored services</p>
          <p className="text-xs text-[#8B949E] mt-1">
            Please check that the PingWatch API backend is running.
          </p>
          <Button
            size="sm"
            variant="secondary"
            onClick={() => refetch()}
            className="mt-4"
          >
            Retry Connection
          </Button>
        </div>
      )}

      {/* Empty State */}
      {!isLoading && !isError && sites.length === 0 && (
        <div className="text-center py-20 px-6 rounded-lg border border-dashed border-[#30363D] bg-[#161B22]/30">
          <div className="w-12 h-12 rounded-full bg-[#00FF87]/10 border border-[#00FF87]/20 flex items-center justify-center text-[#00FF87] mx-auto mb-4">
            <Activity className="h-6 w-6" />
          </div>
          <h3 className="text-base font-semibold text-white">You have no sites yet</h3>
          <p className="text-xs text-[#8B949E] max-w-sm mx-auto mt-1 mb-6">
            Add your first SaaS URL or API health check endpoint to start tracking live uptime and latency.
          </p>
          <Link href="/dashboard/sites/new">
            <Button variant="primary" size="md" className="gap-2 font-mono text-xs">
              <PlusCircle className="h-4 w-4" /> Add your first URL
            </Button>
          </Link>
        </div>
      )}

      {/* Sites Grid */}
      {!isLoading && !isError && sites.length > 0 && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {sites.map((site) => (
            <SiteCard
              key={site.id}
              site={site}
              onDelete={deleteSite}
              isDeleting={isDeleting}
            />
          ))}
        </div>
      )}
    </div>
  );
}
